package com.tekwatt.reporting.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="reports") public class Report {@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private ReportType reportType;@Enumerated(EnumType.STRING)@Column(nullable=false,length=10)private ReportFormat reportFormat;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ReportStatus status;@Column(nullable=false)private Instant periodFrom;@Column(nullable=false)private Instant periodTo;private String fileName;@Column(length=100)private String contentType;@Lob @Column(columnDefinition="LONGBLOB")private byte[] fileContent;@Column(length=1000)private String errorMessage;@Column(nullable=false,updatable=false)private Instant createdAt;private Instant completedAt;protected Report(){}public Report(UUID tenant,ReportType type,ReportFormat format,Instant from,Instant to){id=UUID.randomUUID();tenantId=tenant;reportType=type;reportFormat=format;status=ReportStatus.PENDING;periodFrom=from;periodTo=to;createdAt=Instant.now();}public void complete(String name,byte[] content){fileName=name;contentType=reportFormat.contentType();fileContent=content;status=ReportStatus.COMPLETED;completedAt=Instant.now();}public void fail(String message){status=ReportStatus.FAILED;errorMessage=message==null?"Report generation failed":message.substring(0,Math.min(message.length(),1000));completedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public ReportType getReportType(){return reportType;}public ReportFormat getReportFormat(){return reportFormat;}public ReportStatus getStatus(){return status;}public Instant getPeriodFrom(){return periodFrom;}public Instant getPeriodTo(){return periodTo;}public String getFileName(){return fileName;}public String getContentType(){return contentType;}public byte[] getFileContent(){return fileContent;}public String getErrorMessage(){return errorMessage;}public Instant getCreatedAt(){return createdAt;}public Instant getCompletedAt(){return completedAt;}}
